-- Molten Core loot, gold and loot ids for the four difficulties, rebuilt from the
-- db.exil.es export (hertigservices/ascension-data release exiles-db-export-2026-09-13),
-- the database behind the CoA database site, without its 20-row page cap.
-- Base entries keep their own loot id; Heroic, Mythic and Ascended entries (+100000,
-- +200000, +300000) get their own. World-drop references 24xxx and 34002 already match
-- ours and are reused; the MC-specific references move to 4090011-4090030 because
-- 34026 is an AQ20 table here.
-- Three export quirks that AzerothCore's LootMgr rejects or flags at load time are
-- normalized here (LootMgr.cpp LootStoreItem::IsValid/LootGroup::Verify/CheckLootRefs):
-- - Rows with Chance = 0 and GroupId = 0 (29 corrupt export rows, all non-reference,
--   never actually drop under either database's rules) are dropped instead of inserted.
-- - A row with Chance >= 100 keeps its own GroupId = 0, matching the base data's
--   convention (e.g. reference 34002 is always GroupId 0): AzerothCore rolls a group
--   once and returns the first item whose chance is met, so a guaranteed row sharing a
--   group with rare siblings would always win and made every such group read as over
--   100% total chance; moving it to GroupId 0 keeps it an unconditional drop and lets
--   the siblings' own group total stay under 100%, as intended.
-- - Reference rows get MinCount = MaxCount (this core does not support a differing
--   pair for a reference and only logs it); the export's MaxCount is kept for both.
DELETE FROM `reference_loot_template` WHERE `Entry` = 4090011;
